const status = $("Read publication status").first().json;
const analytics = $("Read analytics snapshots").first().json;
const entries = Array.isArray(analytics.snapshots) ? analytics.snapshots : [];
const providers = status.providers || {};
const blocked = Object.entries(providers).filter(([,value]) => value && value.status === "blocked").map(([key]) => key);
return [{json:{schema_version:1, collected_at:new Date().toISOString(), publishing:{enabled:!!status.enabled, dry_run:!!status.dry_run, blocked_providers:blocked, queue:status.publish_items_by_status||{}, last_cycle:status.last_cycle||{}}, analytics:{snapshot_count:entries.length, provider_reported_metrics:entries.length ? "inspect_snapshot_sources" : "no_data", snapshots:entries.slice(0,20)}, warning:"Publication status and stored snapshots are not evidence of increased organic views. Confirm each metric source."}}];
